window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-76a89949591fc0cb"]={"versions": [{"id": "FIG-76a89949591fc0cb", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Manifest-Spezifikation in AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Design-Zeit-Zuordnung (<code>ProcessDesignToMachineDesignMapping</code>) von Prozessentwürfen (<code>ProcessDesign</code>) zu Maschinenentwürfen (<code>MachineDesign</code>) innerhalb eines übergeordneten Mapping-Containers (<code>ProcessDesignToMachineDesignMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMappingSet</code> (Spezialisierung von <code>ARElement</code>): Bildet die aggregierende Hülle für Zuordnungen und enthält per Komposition (<code>+processDesignToMachineDesignMapping</code>, Multiplizität <code>0..*</code>) Instanzen von <code>ProcessDesignToMachineDesignMapping</code>.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert das Zuordnungselement. Es referenziert über gerichtete Assoziationen:</li>\n<li><code>+processDesign</code>: genau eine Zielinstanz von <code>ProcessDesign</code> (Multiplizität <code>1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Zielinstanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Repräsentiert die Entwurfsdefinition eines Prozesses.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code> und <code>FibexElement</code>): Modelliert die Hardware-/Maschinenarchitektur auf Entwurfsebene mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Verhaltenssequenzen. Die Instanziierung erfolgt im Modellierungsablauf typischerweise durch Aufbau eines <code>ProcessDesignToMachineDesignMappingSet</code>, in dem einzelne Mappings definiert werden, welche jeweils einen <code>ProcessDesign</code> deterministisch auf einen Ziel-<code>MachineDesign</code> abbilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>ProcessDesignToMachineDesignMapping</code> ist ein <code>Identifiable</code>, das zwingend in ein <code>ProcessDesignToMachineDesignMappingSet</code> eingebettet sein muss.</li>\n<li>Jede Zuordnung muss verbindlich genau ein <code>ProcessDesign</code> referenzieren (<code>1</code>).</li>\n<li>Die Zuordnung zu einem <code>MachineDesign</code> ist optional (<code>0..1</code>), womit unvollständige oder maschinenunabhängige Vorentwürfe abbildbar sind.</li>\n<li>Attribute von <code>MachineDesign</code> für Zugriffssteuerung (<code>accessControl</code>) und Teilnetz-Reset (<code>pnResetTimer</code>) sind optional konfigurierbar.</li>\n</ul>"}, {"id": "FIG-b3f1fa2758d9bf7c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Manifest-Spezifikation in AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Design-Zeit-Zuordnung (<code>ProcessDesignToMachineDesignMapping</code>) von Prozessentwürfen (<code>ProcessDesign</code>) zu Maschinenentwürfen (<code>MachineDesign</code>) innerhalb eines übergeordneten Mapping-Containers (<code>ProcessDesignToMachineDesignMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMappingSet</code> (Spezialisierung von <code>ARElement</code>): Bildet die aggregierende Hülle für Zuordnungen und enthält per Komposition (<code>+processDesignToMachineDesignMapping</code>, Multiplizität <code>0..*</code>) Instanzen von <code>ProcessDesignToMachineDesignMapping</code>.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert das Zuordnungselement. Es referenziert über gerichtete Assoziationen:</li>\n<li><code>+processDesign</code>: genau eine Zielinstanz von <code>ProcessDesign</code> (Multiplizität <code>1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Zielinstanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Repräsentiert die Entwurfsdefinition eines Prozesses.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code> und <code>FibexElement</code>): Modelliert die Hardware-/Maschinenarchitektur auf Entwurfsebene mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Verhaltenssequenzen. Die Instanziierung erfolgt im Modellierungsablauf typischerweise durch Aufbau eines <code>ProcessDesignToMachineDesignMappingSet</code>, in dem einzelne Mappings definiert werden, welche jeweils einen <code>ProcessDesign</code> deterministisch auf einen Ziel-<code>MachineDesign</code> abbilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>ProcessDesignToMachineDesignMapping</code> ist ein <code>Identifiable</code>, das zwingend in ein <code>ProcessDesignToMachineDesignMappingSet</code> eingebettet sein muss.</li>\n<li>Jede Zuordnung muss verbindlich genau ein <code>ProcessDesign</code> referenzieren (<code>1</code>).</li>\n<li>Die Zuordnung zu einem <code>MachineDesign</code> ist optional (<code>0..1</code>), womit unvollständige oder maschinenunabhängige Vorentwürfe abbildbar sind.</li>\n<li>Attribute von <code>MachineDesign</code> für Zugriffssteuerung (<code>accessControl</code>) und Teilnetz-Reset (<code>pnResetTimer</code>) sind optional konfigurierbar.</li>\n</ul>"}, {"id": "FIG-ad5e87a0cf8f7c2a", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Modellierung der Manifest-Spezifikation in AUTOSAR Adaptive Platform. Das Diagramm spezifiziert die Design-Zeit-Zuordnung (<code>ProcessDesignToMachineDesignMapping</code>) von Prozessentwürfen (<code>ProcessDesign</code>) zu Maschinenentwürfen (<code>MachineDesign</code>) innerhalb eines übergeordneten Mapping-Containers (<code>ProcessDesignToMachineDesignMappingSet</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMappingSet</code> (Spezialisierung von <code>ARElement</code>): Aggregiert per Komposition (<code>+processDesignToMachineDesignMapping</code>, Multiplizität <code>0..*</code>) Elemente vom Typ <code>ProcessDesignToMachineDesignMapping</code>.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>Identifiable</code>): Zuordnungselement mit gerichteten Assoziationen:</li>\n<li><code>+processDesign</code>: genau eine Zielinstanz von <code>ProcessDesign</code> (Multiplizität <code>1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Zielinstanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Entwurfsdefinition eines Prozesses.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code> und <code>FibexElement</code>): Modelliert die Maschinenentwurfsebene mit folgenden optionalen Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne dynamische Interaktions- oder Verhaltenssequenzen. Die Instanziierung erfolgt im Modellierungsablauf typischerweise durch Aufbau eines <code>ProcessDesignToMachineDesignMappingSet</code>, in dem einzelne Mappings definiert werden, welche jeweils einen <code>ProcessDesign</code> deterministisch auf einen Ziel-<code>MachineDesign</code> abbilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li>Ein <code>ProcessDesignToMachineDesignMapping</code> existiert im Kontext eines übergeordneten <code>ProcessDesignToMachineDesignMappingSet</code>.</li>\n<li>Die Referenz <code>+processDesign</code> ist obligatorisch (<code>1</code>), während <code>+machineDesign</code> optional ist (<code>0..1</code>).</li>\n<li>Konfiguration von Timern für Teilnetz-Management (<code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) und Zugriffssteuerung (<code>accessControl</code>) am <code>MachineDesign</code> sind optional vorgesehen.</li>\n</ul>"}, {"id": "FIG-bc69c7091c23bd56", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Manifest-Modellierung in AUTOSAR Adaptive Platform. Dargestellt ist die direkte Zuordnungsmetaklasse <code>ProcessDesignToMachineDesignMapping</code> als eigenständiges <code>ARElement</code> sowie deren Relationen zu <code>ProcessDesign</code> und <code>MachineDesign</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>ARElement</code>): Eigenständiges Modellierungselement zur Zuordnung zwischen Prozess- und Maschinendesign. Referenziert über gerichtete Assoziationen:</li>\n<li><code>+processDesign</code>: genau eine Zielinstanz von <code>ProcessDesign</code> (Multiplizität <code>1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Zielinstanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Repräsentiert die Entwurfsdefinition eines Prozesses.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code> und <code>FibexElement</code>): Modelliert das Maschinen-Design mit folgenden Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauflogik. Die Zuordnung zwischen <code>ProcessDesign</code> und <code>MachineDesign</code> wird direkt über eigenständige Instanzen von <code>ProcessDesignToMachineDesignMapping</code> auf AUTOSAR-Paketebene vorgenommen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> ist als <code>ARElement</code> ein eigenständiges Top-Level-Element innerhalb von AUTOSAR-Packages und bedarf keines Sets als Container mehr.</li>\n<li>Die Referenz <code>+processDesign</code> muss exakt einmal belegt sein (<code>1</code>).</li>\n<li>Die Referenz <code>+machineDesign</code> ist optional (<code>0..1</code>).</li>\n<li>Attribute <code>accessControl</code>, <code>pncPrepareSleepTimer</code> und <code>pnResetTimer</code> am <code>MachineDesign</code> sind optional (<code>[0..1]</code>).</li>\n</ul>"}, {"id": "FIG-b12f41ae7dd1c994", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Manifest-Modellierung in AUTOSAR Adaptive Platform. Dargestellt ist die direkte Zuordnungsmetaklasse <code>ProcessDesignToMachineDesignMapping</code> als eigenständiges <code>ARElement</code> sowie deren Relationen zu <code>ProcessDesign</code> und <code>MachineDesign</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen in horizontaler Anordnung:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>ARElement</code>): Zentrales Zuordnungselement mit gerichteten Assoziationen:</li>\n<li><code>+processDesign</code>: optional eine Zielinstanz von <code>ProcessDesign</code> (Multiplizität <code>0..1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Zielinstanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert die Prozessentwurfsebene.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code> und <code>FibexElement</code>): Modelliert die Maschinenentwurfsebene mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauflogik. Die Zuordnung zwischen <code>ProcessDesign</code> und <code>MachineDesign</code> wird direkt über eigenständige Instanzen von <code>ProcessDesignToMachineDesignMapping</code> auf AUTOSAR-Paketebene vorgenommen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Kardinalitäten:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> ist ein eigenständiges <code>ARElement</code>.</li>\n<li>Beide Referenzen (<code>+processDesign</code> und <code>+machineDesign</code>) besitzen eine Kardinalität von <code>0..1</code>. Damit sind unvollständige Mappings zulässig, bei denen eine Seite temporär ungebunden bleibt.</li>\n<li>Am <code>MachineDesign</code> sind die Attribute für <code>accessControl</code>, <code>pncPrepareSleepTimer</code> und <code>pnResetTimer</code> jeweils optional definiert.</li>\n</ul>"}, {"id": "FIG-8040206ca999cbb4", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Manifest-Modellierung in AUTOSAR Adaptive Platform. Dargestellt ist die direkte Zuordnungsmetaklasse <code>ProcessDesignToMachineDesignMapping</code> als eigenständiges <code>ARElement</code> sowie deren Relationen zu <code>ProcessDesign</code> und <code>MachineDesign</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen in horizontaler Anordnung:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>ARElement</code>): Zentrales Zuordnungselement mit gerichteten Assoziationen:</li>\n<li><code>+processDesign</code>: optional eine Instanz von <code>ProcessDesign</code> (Multiplizität <code>0..1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Instanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert die Prozessentwurfsebene.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code> und <code>UploadableDesignElement</code>): Modelliert das Maschinen-Design mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauflogik. Die Zuordnung zwischen <code>ProcessDesign</code> und <code>MachineDesign</code> wird direkt über eigenständige Instanzen von <code>ProcessDesignToMachineDesignMapping</code> auf AUTOSAR-Paketebene vorgenommen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Entwicklerhinweise:</p>\n<ul class=\"fig-list\">\n<li><code>MachineDesign</code> fungiert zusätzlich als <code>UploadableDesignElement</code>, wodurch es im Kontext von Software-/Design-Upload-Mechanismen adressierbar ist.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> bildet als <code>ARElement</code> lose gekoppelte 0..1-Beziehungen sowohl zu <code>ProcessDesign</code> als auch zu <code>MachineDesign</code> ab.</li>\n<li>Die Maschinenkonfigurationsparameter (<code>accessControl</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) bleiben optional mit Kardinalität <code>[0..1]</code>.</li>\n</ul>"}, {"id": "FIG-67acf446c3407b04", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Manifest-Modellierung in AUTOSAR Adaptive Platform. Dargestellt ist die direkte Zuordnungsmetaklasse <code>ProcessDesignToMachineDesignMapping</code> als eigenständiges <code>ARElement</code> sowie deren Relationen zu <code>ProcessDesign</code> und <code>MachineDesign</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst drei Metaklassen in horizontaler Anordnung:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>ARElement</code>): Zentrales Zuordnungselement mit gerichteten Assoziationen:</li>\n<li><code>+processDesign</code>: optional eine Instanz von <code>ProcessDesign</code> (Multiplizität <code>0..1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Instanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert die Prozessentwurfsebene.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code> und <code>UploadableDesignElement</code>): Modelliert das Maschinen-Design mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauflogik. Die Zuordnung zwischen <code>ProcessDesign</code> und <code>MachineDesign</code> wird direkt über eigenständige Instanzen von <code>ProcessDesignToMachineDesignMapping</code> auf AUTOSAR-Paketebene vorgenommen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Entwicklerhinweise:</p>\n<ul class=\"fig-list\">\n<li><code>MachineDesign</code> fungiert zusätzlich als <code>UploadableDesignElement</code>, wodurch es im Kontext von Software-/Design-Upload-Mechanismen adressierbar ist.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> bildet als <code>ARElement</code> lose gekoppelte 0..1-Beziehungen sowohl zu <code>ProcessDesign</code> als auch zu <code>MachineDesign</code> ab.</li>\n<li>Die Maschinenkonfigurationsparameter (<code>accessControl</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) bleiben optional mit Kardinalität <code>[0..1]</code>.</li>\n</ul>"}, {"id": "FIG-75b9243ba031368e", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation der Manifest-Modellierung in AUTOSAR Adaptive Platform. Dargestellt ist die direkte Zuordnungsmetaklasse <code>ProcessDesignToMachineDesignMapping</code> als eigenständiges <code>ARElement</code> sowie deren Relationen zu <code>ProcessDesign</code>, <code>MachineDesign</code> und <code>ProcessorCore</code>.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier Metaklassen:</p>\n<ul class=\"fig-list\">\n<li><code>ProcessDesignToMachineDesignMapping</code> (Spezialisierung von <code>ARElement</code>): Zentrales Zuordnungselement mit gerichteten Assoziationen:</li>\n<li><code>+processDesign</code>: optional eine Instanz von <code>ProcessDesign</code> (Multiplizität <code>0..1</code>),</li>\n<li><code>+machineDesign</code>: optional eine Instanz von <code>MachineDesign</code> (Multiplizität <code>0..1</code>),</li>\n<li><code>+shallRunOn</code>: beliebige Anzahl von Instanzen von <code>ProcessorCore</code> (Multiplizität <code>0..*</code>),</li>\n<li><code>+shallNotRunOn</code>: beliebige Anzahl von Instanzen von <code>ProcessorCore</code> (Multiplizität <code>0..*</code>).</li>\n<li><code>ProcessDesign</code> (Spezialisierung von <code>ARElement</code>): Modelliert die Prozessentwurfsebene.</li>\n<li><code>MachineDesign</code> (Spezialisierung von <code>AtpStructureElement</code>, <code>FibexElement</code> und <code>UploadableDesignElement</code>): Modelliert das Maschinen-Design mit den Attributen:</li>\n<li><code>+ accessControl: AccessControlEnum [0..1]</code></li>\n<li><code>+ pncPrepareSleepTimer: TimeValue [0..1]</code></li>\n<li><code>+ pnResetTimer: TimeValue [0..1]</code></li>\n<li><code>ProcessorCore</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert einen Prozessorkern mit dem Attribut:</li>\n<li><code>+ coreId: PositiveInteger [0..1]</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Strukturmodell ohne Ablauflogik. Die Zuordnung zwischen <code>ProcessDesign</code> und <code>MachineDesign</code> sowie die Core-Affinitäten (<code>shallRunOn</code>, <code>shallNotRunOn</code>) zu <code>ProcessorCore</code> werden über eigenständige Instanzen von <code>ProcessDesignToMachineDesignMapping</code> auf AUTOSAR-Paketebene vorgenommen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Modellierungsregeln und Entwicklerhinweise:</p>\n<ul class=\"fig-list\">\n<li><code>MachineDesign</code> fungiert zusätzlich als <code>UploadableDesignElement</code>, wodurch es im Kontext von Software-/Design-Upload-Mechanismen adressierbar ist.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code> bildet als <code>ARElement</code> lose gekoppelte 0..1-Beziehungen sowohl zu <code>ProcessDesign</code> als auch zu <code>MachineDesign</code> ab.</li>\n<li>Über die Assoziationen <code>shallRunOn</code> und <code>shallNotRunOn</code> können Core-Affinitäten und -Ausschlüsse gegenüber <code>ProcessorCore</code> mit Multiplizität <code>0..*</code> definiert werden.</li>\n<li>Die Metaklasse <code>ProcessorCore</code> besitzt das optionale Attribut <code>coreId</code> vom Typ <code>PositiveInteger [0..1]</code>.</li>\n<li>Die Maschinenkonfigurationsparameter (<code>accessControl</code>, <code>pncPrepareSleepTimer</code>, <code>pnResetTimer</code>) bleiben optional mit Kardinalität <code>[0..1]</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-76a89949591fc0cb", "to": "FIG-b3f1fa2758d9bf7c", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Leicht veränderte vertikale Positionierung der Multiplizitäts- und Rollenbezeichner an den Assoziationsenden zu <code>MachineDesign</code> und <code>ProcessDesign</code>.</li>\n</ul>"}, {"from": "FIG-b3f1fa2758d9bf7c", "to": "FIG-ad5e87a0cf8f7c2a", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>MachineDesign</code>: Attribut <code>+ pncPrepareSleepTimer: TimeValue [0..1]</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-ad5e87a0cf8f7c2a", "to": "FIG-bc69c7091c23bd56", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Metaklasse <code>ProcessDesignToMachineDesignMappingSet</code> und deren Kompositionsbeziehung <code>+processDesignToMachineDesignMapping 0..*</code> entfernt.</li>\n<li><code>ProcessDesignToMachineDesignMapping</code>: Stereotyp/Spezialisierung von <code>Identifiable</code> zu <code>ARElement</code> geändert (wird eigenständiges Toplevel-Element).</li>\n</ul>"}, {"from": "FIG-bc69c7091c23bd56", "to": "FIG-b12f41ae7dd1c994", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Horizontales Layout der Klassenanordnung (<code>ProcessDesign</code> links, <code>ProcessDesignToMachineDesignMapping</code> mittig, <code>MachineDesign</code> rechts).</li>\n<li>Assoziation <code>+processDesign</code>: Multiplizität von <code>1</code> auf <code>0..1</code> geändert.</li>\n</ul>"}, {"from": "FIG-b12f41ae7dd1c994", "to": "FIG-8040206ca999cbb4", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>MachineDesign</code>: Zusätzliche Stereotyp-/Generalisierungsklassifikation <code>UploadableDesignElement</code> ergänzt.</li>\n</ul>"}, {"from": "FIG-8040206ca999cbb4", "to": "FIG-67acf446c3407b04", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-67acf446c3407b04", "to": "FIG-75b9243ba031368e", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Metaklasse <code>ProcessorCore</code> (Spezialisierung von <code>Identifiable</code>) mit Attribut <code>+ coreId: PositiveInteger [0..1]</code> hinzugefügt.</li>\n<li>Gerichtete Assoziation <code>+shallRunOn</code> von <code>ProcessDesignToMachineDesignMapping</code> zu <code>ProcessorCore</code> mit Multiplizität <code>0..*</code> hinzugefügt.</li>\n<li>Gerichtete Assoziation <code>+shallNotRunOn</code> von <code>ProcessDesignToMachineDesignMapping</code> zu <code>ProcessorCore</code> mit Multiplizität <code>0..*</code> hinzugefügt.</li>\n</ul>"}]};
